using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class ConfigureFiveTrailRows{
public static string Run(){if(Application.isPlaying)throw new Exception("Edit mode required");var path="Assets/3DBattle/Boss2/GoldenSlashVFX/B2GoldenSlash.prefab";var root=PrefabUtility.LoadPrefabContents(path);
try{var v=root.transform.Find("Golden Crescent and Trails");var a=v.Find("Trails");var b=v.Find("Trails (1)");if(a==null||b==null)throw new Exception("Original pair missing");var old=v.Cast<Transform>().Where(t=>t.name=="Trails"||t.name=="Trails (1)"||t.name.Contains(" Full Height ")).ToArray();var layout=root.AddComponent<B2SlashTrailLayout>();string[] names={"Trail 1 - Top","Trail 2 - Upper Middle","Trail 3 - Center","Trail 4 - Lower Middle","Trail 5 - Bottom"};var rows=new Transform[5];
for(int i=0;i<5;i++){var g=new GameObject(names[i]);g.transform.SetParent(v,false);g.transform.localPosition=Vector3.right*((2-i)*.825f);rows[i]=g.transform;foreach(var source in new[]{a,b}){var copy=UnityEngine.Object.Instantiate(source.gameObject,g.transform);copy.name=source.name;copy.transform.localPosition=source.localPosition;copy.transform.localRotation=source.localRotation;copy.transform.localScale=source.localScale;}}
foreach(var t in old)UnityEngine.Object.DestroyImmediate(t.gameObject);layout.top=rows[0];layout.upperMiddle=rows[1];layout.center=rows[2];layout.lowerMiddle=rows[3];layout.bottom=rows[4];layout.ApplyLengths(1,.7f,.4f,.7f,1);
if(rows.Sum(t=>t.GetComponentsInChildren<ParticleSystem>().Length)!=10)throw new Exception("Not ten systems");layout.ApplyLengths(.8f,.6f,.2f,.5f,.9f);if(Mathf.Abs(layout.center.localScale.z-.2f)>.0001f||Mathf.Abs(layout.top.localScale.z-.8f)>.0001f)throw new Exception("Length control failed");layout.ApplyLengths(1,.7f,.4f,.7f,1);PrefabUtility.SaveAsPrefabAsset(root,path);
}finally{PrefabUtility.UnloadPrefabContents(root);}
var boss=UnityEngine.Object.FindObjectsByType<B2SwordSlash>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(e=>e.gameObject.scene.path=="Assets/Scenes/3DBattleScene.unity");Undo.RecordObject(boss,"Configure five trail lengths");boss.topTrailLength=1;boss.upperMiddleTrailLength=.7f;boss.centerTrailLength=.4f;boss.lowerMiddleTrailLength=.7f;boss.bottomTrailLength=1;EditorUtility.SetDirty(boss);PrefabUtility.RecordPrefabInstancePropertyModifications(boss);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(boss.gameObject.scene);EditorSceneManager.SaveScene(boss.gameObject.scene);Selection.activeGameObject=boss.gameObject;
return "PASS: 5 rows x2=10 systems, independent length controls tested. Top to bottom:1,.7,.4,.7,1. Saved and selected boss Inspector.";
}}
